#pragma once

// Remote TTS engine: a model folder holding remote.toml and voices\<name>.wav.
// The folder is read as a voice model like any other (see TtsEngine::Model), but
// a line is generated by an HTTP service instead of by sherpa-onnx: the service
// gets the text, the reference recording's name and the speed, and answers a wav.
//
// Kept out of TtsEngine.cpp because cpp-httplib needs winsock2.h ahead of
// <Windows.h>, which the plugin's precompiled header cannot allow.

#include <string>
#include <vector>

namespace RemoteTts
{
	struct Config
	{
		std::string url;               // http://host:port[/path]
		int         timeoutMs = 20000; // one line
		int         sampleRate = 24000;  // what the service answers at, until it says otherwise
	};

	// True when a_dir holds remote.toml: the folder is a remote model, whatever
	// else it holds.
	bool IsRemoteModel(const std::string& a_dir);

	// Reads a_dir\remote.toml. false and a_error for a missing file, a bad one,
	// or a url that is not plain http.
	bool ReadConfig(const std::string& a_dir, Config& a_out, std::string& a_error);

	// One line through the service. a_voice is the reference recording's name
	// (empty = the service's own default). Samples come back mono, -1..1.
	bool Synthesize(const Config& a_config, const std::string& a_text, const std::string& a_voice, float a_speed,
		std::vector<float>& a_samples, int& a_sampleRate, std::string& a_error);
}
